export const factsKeyFor = (galleryId, identifier) => (galleryId === "default" ? identifier : `${galleryId}:${identifier}`);
export function createFactsCache(deps) {
    const now = deps.now ?? (() => Date.now());
    const stats = { hits: 0, misses: 0, errors: 0 };
    const listeners = new Set();
    async function read(identifier) {
        try {
            const v = await deps.store.get(deps.keyOf(identifier));
            return v && typeof v.token === "string" && "value" in v ? v : null;
        }
        catch {
            return null;
        }
    }
    async function write(identifier, token, value) {
        try {
            await deps.store.set(deps.keyOf(identifier), { token, value, at: now() });
        }
        catch (e) {
            deps.report?.(new Error("[facts-cache] write failed: " + String(e)));
        }
    }
    return {
        read, write,
        async invalidate(identifier) {
            const key = deps.keyOf(identifier);
            try {
                await deps.store.delete(key);
            }
            catch { /* best-effort */ }
            for (const fn of listeners) {
                try {
                    fn(key);
                }
                catch { /* listener 自理 */ }
            }
        },
        onInvalidated(fn) { listeners.add(fn); return () => { listeners.delete(fn); }; },
        async getOrFetch(identifier, token, source) {
            const c = await read(identifier);
            if (c && c.token === token) {
                stats.hits++;
                return { value: c.value, fromCache: true };
            }
            stats.misses++;
            try {
                const value = await deps.fetch(identifier, source);
                void write(identifier, token, value ?? null);
                return { value: value ?? null, fromCache: false };
            }
            catch (e) {
                stats.errors++;
                if (c)
                    return { value: c.value, fromCache: true }; // 退旧值但不写缓存（token 不被新的污染）
                throw e;
            }
        },
        async clear() { const n = await deps.store.clear(); stats.hits = stats.misses = stats.errors = 0; return n; },
        stats,
    };
}
