import { availableLangs, coveredPacks, logicalName, voiceLangs, voicePacks } from "./packs.js";
const asError = (e) => (e instanceof Error ? e : new Error(String(e)));
export function createSpeechEngine(deps) {
    const channels = new Map(); // engine 名 → 活着的 worker
    let seq = 0;
    let current = null;
    // 合成请求在这里排队、一次只给 worker 一个（worker 本来就一个一个算）：这样没开始的能扔掉（cancelPending）
    const synthQueue = [];
    let synthBusy = false;
    function pumpSynth() {
        if (synthBusy)
            return;
        const job = synthQueue.shift();
        if (!job)
            return;
        synthBusy = true;
        let p;
        try {
            p = job.make();
        }
        catch (e) {
            p = Promise.reject(asError(e));
        }
        p.then(job.resolve, job.reject).finally(() => { synthBusy = false; pumpSynth(); });
    }
    const cancelPending = () => { for (const j of synthQueue.splice(0))
        j.reject(new Error("cancelled")); };
    function voiceOf(id) {
        const v = deps.voices[id];
        if (!v)
            throw new Error(`unknown voice: ${id}`);
        for (const slug of voicePacks(v))
            if (!deps.packs[slug])
                throw new Error(`voice ${id}: pack "${slug}" is not embedded`);
        return v;
    }
    function closeChannel(engine, why) {
        const ch = channels.get(engine);
        if (!ch)
            return;
        channels.delete(engine);
        const err = new Error(why);
        for (const p of ch.pending.values())
            p.reject(err);
        ch.pending.clear();
        try {
            ch.worker.terminate();
        }
        catch { /* ignore */ }
        if (current && deps.voices[current.voice]?.engine === engine)
            current = null;
    }
    function channel(engine) {
        const have = channels.get(engine);
        if (have)
            return have;
        const spec = deps.workers[engine];
        if (!spec)
            throw new Error(`no worker configured for engine "${engine}"`);
        const worker = new Worker(spec.url, spec.type === "module" ? { type: "module" } : undefined);
        const ch = { worker, pending: new Map() };
        worker.onmessage = (e) => {
            const m = e.data;
            const p = ch.pending.get(m.id);
            if (!p)
                return;
            ch.pending.delete(m.id);
            if (m.ok)
                p.resolve(m.result);
            else
                p.reject(new Error(m.error));
        };
        worker.onerror = (e) => { if (channels.get(engine) === ch)
            closeChannel(engine, `read-aloud worker crashed: ${e.message || "unknown"}`); };
        channels.set(engine, ch);
        const init = { engineBase: new URL((deps.engineBase ?? "./").replace(/\/?$/, "/"), document.baseURI).href, packs: deps.packs };
        void send(ch, { op: "init", init }).catch(() => { });
        return ch;
    }
    function send(ch, req) {
        const id = ++seq;
        return new Promise((resolve, reject) => {
            ch.pending.set(id, { resolve: resolve, reject });
            try {
                ch.worker.postMessage({ ...req, id });
            }
            catch (e) {
                ch.pending.delete(id);
                reject(asError(e));
            }
        });
    }
    /** 按音色找 worker 再发（音色不认识、建 worker 失败都走 reject，不同步抛）。 */
    function call(make, voice) {
        try {
            const v = voiceOf(voice);
            return send(channel(v.engine), make(v));
        }
        catch (e) {
            return Promise.reject(asError(e));
        }
    }
    return {
        async load(voice, opts) {
            const v = voiceOf(voice);
            const names = Object.keys(opts.override ?? {});
            const covered = coveredPacks(v, deps.packs, names);
            // 递进来 = 分片数和清单一致（每片的字节数到 worker 里拼文件时再核）；被本地文件整个顶替的包不递也算有
            const given = (slug) => { const c = opts.chunks[slug]; return !!c && c.length === deps.packs[slug].manifest.chunks.length; };
            const has = (slug) => given(slug) || covered.has(slug);
            const wanted = opts.langs ?? voiceLangs(v);
            const langs = availableLangs(v, has).filter((l) => wanted.includes(l));
            if (!langs.length)
                throw new Error("pack-missing");
            for (const other of [...channels.keys()])
                if (other !== v.engine)
                    closeChannel(other, "switched to a voice of another engine");
            // 递了的包都装（顶替过的也装，好拿原配置核对）；只有「被顶替 + 没递」的包跳过，它的文件名允许 override 新增
            const all = voicePacks(v, langs);
            const slugs = all.filter(given);
            const free = all.filter((s) => !given(s)).flatMap((s) => deps.packs[s].manifest.files.map((f) => logicalName(f.path)));
            const chunks = {};
            for (const s of slugs)
                chunks[s] = [...opts.chunks[s]];
            const ov = Object.entries(opts.override ?? {}).sort(([x], [y]) => (x < y ? -1 : 1));
            const tag = ov.map(([n, b]) => { const f = b; return `${n}=${f.name ?? ""}:${b.size}:${f.lastModified ?? ""}`; }).join(";"); // a different file -> a different load
            const override = ov.map(([name, data]) => ({ name, data }));
            let r;
            try {
                r = await send(channel(v.engine), { op: "load", engine: v.engine, key: `${voice}|${slugs.join(",")}|${tag}`, slugs, chunks, ...(override.length ? { override, free } : {}) });
            }
            catch (e) {
                current = null;
                throw e;
            } // the worker dropped the previous load before trying this one
            const got = r.langs ? langs.filter((l) => r.langs.includes(l)) : langs;
            current = { voice, langs: got, override: override.map((o) => o.name), preset: r.preset === true };
            return { voice, langs: got, alreadyLoaded: r.alreadyLoaded, createMs: r.createMs, sampleRate: r.sampleRate, speakers: r.speakers, override: [...current.override], preset: current.preset };
        },
        loaded: () => (current ? { voice: current.voice, langs: [...current.langs], override: [...current.override], preset: current.preset } : null),
        synth(text, o) {
            if (!current)
                return Promise.reject(new Error("no voice loaded"));
            return new Promise((resolve, reject) => {
                synthQueue.push({ make: () => {
                        if (!current)
                            return Promise.reject(new Error("no voice loaded"));
                        return call(() => ({ op: "synth", text, lang: o.lang, speaker: o.speaker ?? 0, speed: o.speed ?? 1, steadiness: Math.min(1, Math.max(0, Number.isFinite(o.steadiness) ? o.steadiness : 0)), whole: o.whole !== false, preset: Number.isFinite(o.preset) ? Math.trunc(o.preset) : undefined }), current.voice);
                    }, resolve, reject });
                pumpSynth();
            });
        },
        cancelPending,
        dispose() { cancelPending(); for (const engine of [...channels.keys()])
            closeChannel(engine, "read-aloud engine disposed"); current = null; },
    };
}
